-- Source-labelled content enrichment for the previously researched 50-college batch.
-- The writing is original synthesis. Unsupported fees, outcomes and campus claims are not invented.
BEGIN;

DO $preflight$
DECLARE
  requested_slug text;
  matches integer;
BEGIN
  FOREACH requested_slug IN ARRAY ARRAY[
    'a-b-shetty-memorial-institute-of-dental-sciences-absmids-mangalore',
    'a-radiant-institute-of-management-and-technology-arimt-meerut',
    'a-d-patel-institute-of-technology-adit-vallabh-vidyanagar',
    'a-k-choudhury-school-of-information-technology-kolkata',
    'a-p-shah-institute-of-technology-apsit-thane',
    'a-v-patil-degree-college-of-arts-science-and-commerce-gulbarga',
    'acpm-dental-college-dhule',
    'acs-medical-college-and-hospital-chennai',
    'adm-college-for-women-admc-nagapattinam',
    'ag-amp-sg-siddhartha-degree-college-of-arts-and-science-krishna',
    'ag-college-of-education-coimbatore',
    'aj-college-of-science-and-technology-thonnakkal-thiruvananthapuram',
    'aj-institute-of-dental-sciences-mangalore',
    'ajk-mass-communication-research-centre-new-delhi',
    'akd-dharmaraja-college-for-women-rajapalayam',
    'akg-memorial-co-operative-college-of-nursing-kannur',
    'akk-new-law-academy-pune',
    'akt-memorial-college-of-education-villupuram',
    'am-college-gaya',
    'am-shaikh-homoeopathic-medical-college-asmc-belgaum',
    'ame039s-dental-college-and-hospital-raichur',
    'amreddy-memorial-college-of-pharmacy-guntur',
    'apc-mahalaxmi-college-for-women-thoothukudi',
    'ar-college-of-engineering-and-technology-arcet-tirunelveli',
    'ar-engineering-college-arec-villupuram',
    'asl-pauls-college-of-engineering-amp-technology-kinathukkadavu-aslpcet-coimbatore',
    'av-college-of-arts-science-and-commerce-av-college-hyderabad',
    'avc-college-of-engineering-avcce-nagapattinam',
    'awh-college-of-education-calicut',
    'aadhi-bhagawan-college-of-pharmacy-chennai',
    'aadinath-mahila-teacher039s-training-college-udaipur',
    'aakash-college-of-education-fatehabad',
    'aakash-college-of-education-hisar',
    'aakash-institute-of-business-management-aibm-mallathalli-bangalore',
    'aakashline-institute-new-delhi',
    'aakson-institute-for-management-studies-aims-bangalore',
    'aalim-muhammed-salegh-academy-of-architecture-chennai',
    'aalim-muhammed-salegh-college-of-engineering-aalimec-chennai',
    'aarupadai-veedu-institute-of-technology-avit-chennai',
    'aarupadai-veedu-medical-college-avmc-pondicherry',
    'aasee-college-of-education-karur',
    'aashlar-business-school-abs-mathura',
    'aayojan-school-of-architecture-asa-jaipur',
    'abacus-institute-of-computer-applications-aica-hadapsar-pune',
    'abacus-institute-of-engineering-and-management-hooghly',
    'abasaheb-garware-institute-of-management-studies-agims-sangli',
    'abasaheb-marathe-arts-and-new-commerce-science-college-ratnagiri',
    'abasaheb-parvekar-mahavidyalaya-yavatmal',
    'abdul-aziz-ansari-degree-college-jaunpur',
    'abdul-razak-degree-college-ardc-jyotiba-phule-nagar'
  ]::text[]
  LOOP
    SELECT count(*) INTO matches FROM public.colleges WHERE slug = requested_slug;
    IF matches <> 1 THEN
      RAISE EXCEPTION 'Expected exactly one production college slug %, found %', requested_slug, matches;
    END IF;
  END LOOP;
END
$preflight$;


UPDATE public.colleges
SET
  description = '<h2>What students should know about A B Shetty Memorial Institute of Dental Sciences</h2><p>A B Shetty Memorial Institute of Dental Sciences is listed as a dental institution. 11 programmes were reviewed, including BDS - Bachelor of Dental Surgery, MDS Conservative Dentistry and Endodontics, MDS Oral and Maxillofacial Pathology and Oral Microbiology, MDS Oral and Maxillofacial Surgery, and additional listed options. The programme catalogue is supported by the institution or its controlling university.</p><p>This profile separates verified programme information from details that still need confirmation. Students should match the exact course, intake year and campus before relying on an admission, fee or outcome claim.</p><h2>Courses reviewed</h2><p>11 programmes were reviewed, including BDS - Bachelor of Dental Surgery, MDS Conservative Dentistry and Endodontics, MDS Oral and Maxillofacial Pathology and Oral Microbiology, MDS Oral and Maxillofacial Surgery, and additional listed options.</p><h2>How to evaluate this college</h2><p>For dental programmes, confirm the current counselling authority, qualifying examination, internship rules, seat category and document schedule before applying.</p><h2>Source note</h2><p>Current official admissions catalogue for 2026-27. Certificate offerings are advertised separately and are not merged into this core programme list.</p><ul><li><a href="https://nitte.edu.in/absmids/" rel="nofollow noopener" target="_blank">Reviewed source 1</a></li><li><a href="https://nitte.edu.in/absmids/admissions.php" rel="nofollow noopener" target="_blank">Reviewed source 2</a></li></ul><h2>Frequently asked questions</h2><h3>Are the listed courses current?</h3><p>The published course names were checked against the reviewed primary sources. The admission cycle and intake should still be confirmed before applying.</p><h3>Are the fees verified?</h3><p>No. A complete programme, year and category mapping was not established, so this pass does not publish a numeric fee.</p><h3>What should an applicant verify first?</h3><p>Confirm the exact programme, recognition or affiliation, eligibility, admission route, total payable amount and document deadline through an authorised source.</p>',
  page_summary = 'A B Shetty Memorial Institute of Dental Sciences: 11 reviewed programmes, admission checks, campus facilities, career context and clearly labelled source status.',
  eligibility_criteria = '<h2>Eligibility</h2><p>For dental programmes, confirm the current counselling authority, qualifying examination, internship rules, seat category and document schedule before applying.</p><p>Do not assume that the same rule applies to every course. Use the latest programme notice for subjects, marks, category conditions and documents.</p>',
  admission_process = '<h2>Admission process</h2><ol><li>Select the exact programme and intake year.</li><li>Open the authorised admission notice or counselling portal.</li><li>Check eligibility, recognition, seat category and required documents.</li><li>Apply through the stated channel and retain the acknowledgement.</li><li>Confirm the final payable amount before completing admission.</li></ol><p>For dental programmes, confirm the current counselling authority, qualifying examination, internship rules, seat category and document schedule before applying.</p>',
  placement_content = '<h2>Placements and career outcomes</h2><p>Dental outcomes depend on clinical competence, registration, internship completion and the chosen speciality. Compare internship exposure and programme-level disclosures rather than relying on a single package claim.</p><p>No campus-specific recruiter or salary claim is added unless it was supported by a reviewed disclosure. Ask for a recent programme-level report that states the batch, participating students and role details.</p>',
  facilities_content = '<h2>Facilities to verify</h2><p>For a useful campus comparison, verify teaching clinics, laboratories, patient exposure, radiology access, library resources and the hospital or clinical training arrangement.</p><p>Availability can differ by department and academic year, so confirm access for the exact programme rather than relying on a general campus photograph.</p>',
  hostel_life = '<h2>Hostel and student life</h2><p>A current hostel allocation, room type, mess charge and campus-specific rule set was not established in this pass. Applicants who need accommodation should request the latest hostel notice and total annual cost before paying.</p>',
  scholarship_details = '<h2>Scholarships</h2><p>No named scholarship is presented as guaranteed in this pass. Check institute notices and the relevant government scholarship portals for eligibility, income, category, merit, renewal and deadline conditions.</p>',
  rankings_content = '<h2>Rankings, approvals and recognition</h2><p>Use only a ranking that identifies the publisher, year, category and exact campus. Programme recognition and affiliation should be checked independently because a general institutional claim may not cover every course.</p>',
  meta_title = left(name || ' Courses, Admission and Campus Guide', 70),
  meta_description = 'Explore A B Shetty Memorial Institute of Dental Sciences courses, admissions, facilities and career context. See what is source-verified and what applicants sho',
  meta_keywords = 'A B Shetty Memorial Institute of Dental Sciences, courses, admission, eligibility, facilities, placements, hostel, scholarships, approvals',
  data_clean_method = 'official_source_content',
  official_source_clean_pass_count = coalesce(official_source_clean_pass_count, 0) + 1,
  requires_official_source_refresh = true,
  data_clean_audit_note = 'Campus-specific content pass completed from reviewed sources. Courses are verified; fees and unsupported outcome claims remain blank or explicitly unverified. Further source refresh remains required for time-sensitive sections.',
  data_source_urls = coalesce(data_source_urls, '[]'::jsonb) || jsonb_build_array('{"batch":"college-source-content-refresh-next-50","checked_at":"2026-07-30","writing_policy":"original_source_grounded_no_large_dashes","catalogue_status":"verified"}'::jsonb),
  data_last_checked_at = '2026-07-30T00:00:00+05:30'::timestamptz,
  official_source_cleaned_at = now(),
  updated_at = now()
WHERE slug = 'a-b-shetty-memorial-institute-of-dental-sciences-absmids-mangalore';

